/**
 * @brief uart init
 *
 * @param[in] port_id: uart port id, id index starts at 0
 * in linux platform,
 * high 16 bits aslo means uart type,
 * it's value must be one of the TUYA_UART_TYPE_E type
 * the low 16bit - means uart port id
 * you can input like this TUYA_UART_PORT_ID(TUYA_UART_SYS, 2)
 * @param[in] cfg: uart config
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_uart_init(TUYA_UART_NUM_E port_id, TUYA_UART_BASE_CFG_T *cfg)
{
    // --- BEGIN: user implements ---
    UART2_Params uartParams;

    if (cfg == NULL) {
        return OPRT_INVALID_PARM;
    }

    // Initialize default parameters
    UART2_Params_init(&uartParams);

    // Map Tuya Config to TI UART2 Params
    uartParams.baudRate = cfg->baudrate;
    
    // Parity Mapping - Fixed Enums
    if (cfg->parity == TUYA_UART_PARITY_TYPE_NONE) {
        uartParams.parityType = UART2_Parity_NONE;
    } else if (cfg->parity == TUYA_UART_PARITY_TYPE_EVEN) {
        uartParams.parityType = UART2_Parity_EVEN;
    } else if (cfg->parity == TUYA_UART_PARITY_TYPE_ODD) {
        uartParams.parityType = UART2_Parity_ODD;
    }

    // Stop Bits Mapping - Fixed Member name and Enums
    if (cfg->stopbits == TUYA_UART_STOP_LEN_1BIT) {
        uartParams.stopBits = UART2_StopBits_1;
    } else if (cfg->stopbits == TUYA_UART_STOP_LEN_2BIT) {
        uartParams.stopBits = UART2_StopBits_2;
    }

    // Data Bits Mapping - Fixed Enums
    if (cfg->databits == TUYA_UART_DATA_LEN_8BIT) {
        uartParams.dataLength = UART2_DataLen_8;
    } else if (cfg->databits == TUYA_UART_DATA_LEN_7BIT) {
        uartParams.dataLength = UART2_DataLen_7;
    }

    // Mode: Blocking is used for stability during initial porting/logging
    uartParams.readMode = UART2_Mode_BLOCKING;
    uartParams.writeMode = UART2_Mode_BLOCKING;
    
    // If handle exists, close it first to allow re-init
    if (uartHandle != NULL) {
        UART2_close(uartHandle);
        uartHandle = NULL;
    }

    // Open UART with index 0
    uartHandle = UART2_open(TUYA_UART_INDEX, &uartParams);

    if (uartHandle == NULL) {
        return OPRT_COM_ERROR;
    }

    return OPRT_OK;
    // --- END: user implements ---
}

